-- Sprint 7: Add status_history JSONB column to bookings table
-- Tracks all status transitions with actor and timestamp
-- Used by AppointmentTimeline + AppointmentDetailDrawer components

-- Add column (safe with default null — no backfill needed for existing rows)
ALTER TABLE bookings
  ADD COLUMN IF NOT EXISTS status_history JSONB DEFAULT '[]'::jsonb NOT NULL;

-- GIN index for JSONB querying (e.g. audit searches)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_bookings_status_history
  ON bookings USING GIN (status_history);

-- Trigger function: appends a history entry whenever booking status changes
CREATE OR REPLACE FUNCTION append_booking_status_history()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  actor_id TEXT;
  entry JSONB;
BEGIN
  -- Only fire when status actually changes
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  -- Resolve actor: use auth.uid() if available, else 'system'
  actor_id := COALESCE(auth.uid()::text, 'system');

  entry := jsonb_build_object(
    'from', OLD.status::text,
    'to',   NEW.status::text,
    'at',   NOW()::text,
    'by',   actor_id
  );

  NEW.status_history := COALESCE(NEW.status_history, '[]'::jsonb) || jsonb_build_array(entry);

  RETURN NEW;
END;
$$;

-- Attach trigger to bookings table (replace if exists to make migration idempotent)
DROP TRIGGER IF EXISTS trg_bookings_status_history ON bookings;

CREATE TRIGGER trg_bookings_status_history
  BEFORE UPDATE OF status
  ON bookings
  FOR EACH ROW
  EXECUTE FUNCTION append_booking_status_history();

-- RLS note: status_history is readable via existing bookings RLS policies
-- (studio members can read bookings in their studio).
-- status_history is never directly writable by client — only the trigger writes to it.
-- Grant no additional permissions.

  JOIN public.clients  c  ON c.id = b.client_id
  LEFT JOIN public.services sv ON sv.id = b.service_id
  WHERE b.booking_token = p_token
  LIMIT 1;
$$;

